function findIndex(nums: number[], target: number): number {
  let lo = 0, hi = nums.length - 1; // target, if present, is in nums[lo..hi]
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

