function findIndex(nums: number[], target: number): number {
  let lo = 0, hi = nums.length; // answer is in [lo, hi); hi itself is never read
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid; // mid might be the first value >= target, so keep it
  }
  return lo < nums.length && nums[lo] === target ? lo : -1;
}

